{
  "info": {
    "title": "UAE Insurance API",
    "description": "## UAE Open Finance Insurance API Specification",
    "version": "v2.2-rc2"
  },
  "servers": [
    {
      "url": "/open-finance/insurance/v2.2"
    }
  ],
  "source_path": "/insurance-consents/{ConsentId}",
  "operations": {
    "get": {
      "operationId": "InsuranceConsentsByConsentId_read",
